text:
{
 "title": "地方税法等の改正",
 "lead": {
  "es": "個人《こじん》の住民税《じゅうみんぜい》や会社《かいしゃ》にかかる事業税《じぎょうぜい》、土地《とち》や建物《たてもの》にかかる税金《ぜいきん》など、地方《ちほう》の税金《ぜいきん》のきまりを変《か》えた法律《ほうりつ》です。",
  "hs": "個人住民税、法人事業税《ほうじんじぎょうぜい》、固定資産税《こていしさんぜい》・都市計画税、森林環境譲与税《しんりんかんきょうじょうよぜい》など、地方の税金の決まりを変えた法律。",
  "std": "個人住民税、法人事業税、固定資産税・都市計画税、森林環境譲与税などを改正する法律。",
  "univ": "個人住民税、法人事業税、固定資産税及び都市計画税、森林環境譲与税の改正等を行う地方税法等の一部を改正する法律。"
 },
 "facts": [
  {
   "es": "令和《れいわ》6年度分《ねんどぶん》の個人《こじん》の住民税《じゅうみんぜい》で、決《き》まった金額《きんがく》を税金《ぜいきん》から減《へ》らす「定額減税《ていがくげんぜい》」をします。",
   "hs": "令和6年度分の個人住民税で、定額減税《ていがくげんぜい》（決まった額を税金から差し引くこと）を行う。",
   "std": "令和6年度分の個人住民税について、定額減税を実施する。",
   "univ": "個人住民税の改正：令和6年度分の個人住民税について、定額減税を実施する。"
  },
  {
   "es": "お金《かね》の元手《もとで》（資本金《しほんきん》）を減《へ》らすことなどで、「外形標準課税《がいけいひょうじゅんかぜい》」（会社《かいしゃ》の大《おお》きさなどで決《き》まる税金《ぜいきん》）がかかる会社《かいしゃ》が減《へ》っていることなどに対応《たいおう》するため、どの会社《かいしゃ》にかけるかを見直《みなお》します。",
   "hs": "減資《げんし》（資本金を減らすこと）などで外形標準課税《がいけいひょうじゅんかぜい》の対象の法人《ほうじん》が減っていることなどの課題に対応するため、法人事業税の外形標準課税の対象となる法人を見直す。",
   "std": "減資などで外形標準課税の対象法人が減っていることなどの課題に対応するため、法人事業税の外形標準課税の適用対象法人を見直す。",
   "univ": "法人事業税の改正：減資等により外形標準課税の対象法人が減少していること等の課題に対応するため、その適用対象法人の見直しを行う。"
  },
  {
   "es": "令和《れいわ》6年度《ねんど》に土地《とち》などの値打《ねう》ちを見直《みなお》すとき（評価替《ひょうかが》え）に、固定資産税《こていしさんぜい》と都市計画税《としけいかくぜい》で、今《いま》の土地《とち》の負担《ふたん》を調整《ちょうせい》するしくみなどを続《つづ》けます。",
   "hs": "令和6年度の評価替え（土地などの価格の見直し）にあたり、固定資産税《こていしさんぜい》と都市計画税で、今の土地の負担調整措置《ふたんちょうせいそち》などを続ける。",
   "std": "固定資産税・都市計画税について、令和6年度の評価替えにあたり、現行の土地の負担調整措置などを継続する。",
   "univ": "固定資産税及び都市計画税の改正：令和6年度の評価替えに当たり、現行の土地に係る負担調整措置等を継続する。"
  },
  {
   "es": "森林環境譲与税《しんりんかんきょうじょうよぜい》（森林《しんりん》のために国《くに》から地方《ちほう》に配《くば》るお金《かね》）の配《くば》り方《かた》の基準《きじゅん》を見直《みなお》します。",
   "hs": "森林環境譲与税《しんりんかんきょうじょうよぜい》（森林のために国から地方に配る税）について、配り方の基準（譲与基準《じょうよきじゅん》）を見直す。",
   "std": "森林環境譲与税について、譲与基準を見直す。",
   "univ": "森林環境譲与税の改正：譲与基準の見直しを行う。"
  },
  {
   "es": "税金《ぜいきん》を軽《かる》くするしくみなどを整理《せいり》します。",
   "hs": "税負担軽減措置《ぜいふたんけいげんそち》（税金を軽くする特別な仕組み）などを整理する。",
   "std": "税負担軽減措置などの整理合理化などを行う。",
   "univ": "その他：税負担軽減措置等の整理合理化等を行う。"
  },
  {
   "es": "この法律《ほうりつ》は、一部《いちぶ》をのぞいて、令和《れいわ》6年《ねん》4月《がつ》1日《ついたち》から使《つか》われ始《はじ》めます。",
   "hs": "この法律は、一部を除き、令和6年4月1日から施行《しこう》される。",
   "std": "一部を除き、令和6年4月1日から施行する。",
   "univ": "施行期日：この法律は、一部を除き、令和6年4月1日から施行する。"
  }
 ]
}
